context_title:
teansformers llm zig plugin build kenyszeriti  szoftveresen hogy a text tartalmst amit kap a model usertol tenyleges karakter by karakter olvassa el es jegyezze meg a beszelgetesbe de tenyleg h ne csoda prompt hanem a zig komponensel fejleszteni egy olyst hogy ez a dolga es nem rajta mulik h elolvassa e vagy sem hanem csinalja mert nem tud mast csinalni azt ennyi

de most meglevo llmekhet kell kifejezetten amit inregralok appomba
ehhez kell:

zig
const std = @import("std");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var client: std.http.Client = .{ .allocator = allocator };
    defer client.deinit();

    const uri = try std.Uri.parse("https://api.hpc-ai.com/inference/v1/chat/completions");

    const body = 
        \\{"model":"xiaomi/mimo-v2.5-pro","messages":[{"role":"system","content":"You are a helpful assistant."},{"role":"user","content":"What is AI?"}]}
    ;

    const headers = &[_]std.http.Header{
        .{ .name = "content-type", .value = "application/json" },
        .{ .name = "authorization", .value = "Bearer <Your API Key>" },
    };

    var req = try client.open(.POST, uri, .{ .headers = headers });
    req.transfer_encoding = .{ .content_length = body.len };
    try req.send();
    try req.writer().writeAll(body);
    try req.finish();
    try req.wait();

    const resp_body = try req.reader().readAllAlloc(allocator, 1024 * 1024);
    defer allocator.free(resp_body);

    const ChatResponse = struct {
        choices: []const struct {
            message: struct {
                content: ?[]const u8,
            },
        },
    };

    const parsed = try std.json.parseFromSlice(ChatResponse, allocator, resp_body, .{});
    defer parsed.deinit();

    const content = parsed.value.choices[0].message.content orelse "";
    std.debug.print("{s}\n", .{content});
}

